package app.studyhub.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(Exception.class) ResponseEntity<Map<String,String>> handle(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("code","INTERNAL_ERROR","message","No se pudo procesar la solicitud."));} }
